/**
 * PizZip (Lightweight standalone docx zip engine for offline browser execution)
 */

(function (global) {
  const CRC32_TABLE = (function() {
    let c, table = [];
    for (let n = 0; n < 256; n++) {
      c = n;
      for (let k = 0; k < 8; k++) {
        c = ((c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1));
      }
      table[n] = c;
    }
    return table;
  })();

  function crc32(buf) {
    let crc = 0 ^ (-1);
    for (let i = 0; i < buf.length; i++) {
      crc = (crc >>> 8) ^ CRC32_TABLE[(crc ^ buf[i]) & 0xFF];
    }
    return (crc ^ (-1)) >>> 0;
  }

  class PizZip {
    constructor(binaryData) {
      this.files = {};
      if (binaryData) {
        this.load(binaryData);
      }
    }

    load(data) {
      const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);
      const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);

      let pos = 0;
      let foundHeader = false;
      while (pos < bytes.length - 4) {
        const sig = view.getUint32(pos, true);
        if (sig === 0x04034b50) { // Local file header
          foundHeader = true;
          const compMethod = view.getUint16(pos + 8, true);
          const compSize = view.getUint32(pos + 18, true);
          const uncompSize = view.getUint32(pos + 22, true);
          const nameLen = view.getUint16(pos + 26, true);
          const extraLen = view.getUint16(pos + 28, true);
          const nameBytes = bytes.slice(pos + 30, pos + 30 + nameLen);
          const name = new TextDecoder('utf-8').decode(nameBytes);
          const dataStart = pos + 30 + nameLen + extraLen;

          const fileBytes = bytes.slice(dataStart, dataStart + (compMethod === 0 ? uncompSize : compSize));
          this.files[name] = {
            name,
            data: fileBytes,
            compMethod,
            uncompSize,
            asText: () => new TextDecoder('utf-8').decode(fileBytes)
          };

          pos = dataStart + (compMethod === 0 ? uncompSize : compSize);
        } else {
          pos++;
        }
      }

      if (!foundHeader) {
        throw new Error('Файл шаблона поврежден или не является валидным архивом .docx');
      }
    }

    file(name, content) {
      if (content === undefined) {
        return this.files[name] || null;
      }
      let bytes = content;
      if (typeof content === 'string') {
        bytes = new TextEncoder().encode(content);
      }
      this.files[name] = {
        name,
        data: bytes,
        compMethod: 0,
        uncompSize: bytes.length,
        asText: () => typeof content === 'string' ? content : new TextDecoder('utf-8').decode(bytes)
      };
      return this;
    }

    generate(options = {}) {
      const type = options.type || 'uint8array';
      let fileRecords = [];
      let centralDir = [];
      let offset = 0;

      for (const filename in this.files) {
        const f = this.files[filename];
        const data = f.data instanceof Uint8Array ? f.data : new TextEncoder().encode(f.data);
        const nameBytes = new TextEncoder().encode(filename);
        const crc = crc32(data);
        const size = data.length;

        // Local Header
        const header = new Uint8Array(30 + nameBytes.length);
        const view = new DataView(header.buffer);
        view.setUint32(0, 0x04034b50, true);
        view.setUint16(4, 20, true);
        view.setUint16(6, 0, true);
        view.setUint16(8, 0, true);
        view.setUint16(10, 0, true);
        view.setUint16(12, 0, true);
        view.setUint32(14, crc, true);
        view.setUint32(18, size, true);
        view.setUint32(22, size, true);
        view.setUint16(26, nameBytes.length, true);
        view.setUint16(28, 0, true);
        header.set(nameBytes, 30);

        fileRecords.push(header);
        fileRecords.push(data);

        // Central Directory Entry
        const cd = new Uint8Array(46 + nameBytes.length);
        const cdView = new DataView(cd.buffer);
        cdView.setUint32(0, 0x02014b50, true);
        cdView.setUint16(4, 20, true);
        cdView.setUint16(6, 20, true);
        cdView.setUint16(8, 0, true);
        cdView.setUint16(10, 0, true);
        cdView.setUint16(12, 0, true);
        cdView.setUint14 && cdView.setUint14(14, 0, true);
        cdView.setUint32(16, crc, true);
        cdView.setUint32(20, size, true);
        cdView.setUint32(24, size, true);
        cdView.setUint16(28, nameBytes.length, true);
        cdView.setUint16(30, 0, true);
        cdView.setUint16(32, 0, true);
        cdView.setUint16(34, 0, true);
        cdView.setUint16(36, 0, true);
        cdView.setUint32(38, 0, true);
        cdView.setUint32(42, offset, true);
        cd.set(nameBytes, 46);

        centralDir.push(cd);
        offset += header.length + size;
      }

      const cdOffset = offset;
      let cdSize = 0;
      centralDir.forEach(cd => cdSize += cd.length);

      const eocd = new Uint8Array(22);
      const eocdView = new DataView(eocd.buffer);
      eocdView.setUint32(0, 0x06054b50, true);
      eocdView.setUint16(4, 0, true);
      eocdView.setUint16(6, 0, true);
      eocdView.setUint16(8, Object.keys(this.files).length, true);
      eocdView.setUint16(10, Object.keys(this.files).length, true);
      eocdView.setUint32(12, cdSize, true);
      eocdView.setUint32(16, cdOffset, true);
      eocdView.setUint16(20, 0, true);

      const totalLen = offset + cdSize + 22;
      const result = new Uint8Array(totalLen);
      let pos = 0;

      for (const rec of fileRecords) {
        result.set(rec, pos);
        pos += rec.length;
      }
      for (const cd of centralDir) {
        result.set(cd, pos);
        pos += cd.length;
      }
      result.set(eocd, pos);

      if (type === 'blob') {
        return new Blob([result], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
      }
      return result;
    }
  }

  global.PizZip = PizZip;
})(window);
